data.value:
CREATE TABLE company_bank_profiles (
 sequence BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
 company_id UUID NOT NULL, revision_id TEXT NOT NULL, known_ticks BIGINT NOT NULL,
 content_hash TEXT NOT NULL, bank_data JSONB NOT NULL, payload JSONB NOT NULL,
 UNIQUE(company_id,revision_id), UNIQUE(company_id,known_ticks));
CREATE INDEX ix_company_bank_profile_asof ON company_bank_profiles(company_id,known_ticks DESC);
